import numpy as np
import numpy.linalg as la
def loadxyz(fn):
    with open(fn) as f:
        ls = f.read().splitlines()
    n = int(ls[0]); atoms=[]
    for ln in ls[2:2+n]:
        p = ln.split()
        atoms.append((p[0], np.array([float(p[1]),float(p[2]),float(p[3])])))
    return atoms
A = loadxyz('opt1.xyz')
def d(i,j): return np.linalg.norm(A[i][1]-A[j][1])
P = np.array([A[i][1] for i in range(1,11)])
c = P.mean(axis=0); Pc = P-c
u,s,vt = la.svd(Pc)
dev = Pc @ vt[2]
print("quinoline rms deviation from plane: %.3f" % np.sqrt((dev**2).mean()))
VDW = {'H':1.20,'C':1.70,'N':1.55,'O':1.52,'F':1.47,'P':1.80,'S':1.80,'Si':2.10,'Rh':1.60}
bad=[]
for i in range(len(A)):
    for j in range(i+1,len(A)):
        dd = d(i,j)
        si,sj = A[i][0],A[j][0]
        if dd < 0.62*(VDW[si]+VDW[sj]):
            bad.append((round(dd,2),i,si,j,sj))
print("very close pairs (<0.62*vdW):", len(bad))
for b in sorted(bad)[:20]: print("  ",b)
# H-H contacts specifically below 1.8
hh=[]
for i in range(len(A)):
    for j in range(i+1,len(A)):
        if A[i][0]=='H' and A[j][0]=='H':
            dd=d(i,j)
            if dd<1.8: hh.append((round(dd,2),i,j))
print("H-H < 1.8:", len(hh), sorted(hh)[:8])
